def remove_odd(l):
    # Determine the type of the input
    if isinstance(l, tuple):
        return tuple(num for num in l if num % 2 == 0)
    elif isinstance(l, list):
        return [num for num in l if num % 2 == 0]
    else:
        raise TypeError("Input must be a list or tuple")
